import TransposeFollowup.RawDimensionLoader
import TransposeFollowup.NativeIOZipper
open TransposeFollowup FixedTapeCompiler CopyMachine

def advanceBits (m n : Nat) : List Bool := (List.range m).map (fun j => n.testBit j)
def advanceWidth (k : Nat) : Nat := max 1 (k-1).size
def advanceWords (m k : Nat) : DimensionAdvance.Words :=
  ⟨advanceBits m k,advanceBits m (k*k),advanceBits m (advanceWidth k),advanceBits m (2^advanceWidth k)⟩
def advanceMarkedExact (word : Tape Bool) (xs : List Bool) : Bool :=
  decide (word.left.headD .blank=.start) && word.left.tail.all (fun s => decide (s=.blank)) &&
  decide (word.right.take (xs.length+1)=symbols xs++[.stop]) &&
  (word.right.drop (xs.length+1)).all (fun s => decide (s=.blank))
def advancePrepared (word : Tape Bool) : Bool :=
  decide (word.left.headD .blank=.start) && word.left.tail.all (fun s => decide (s=.blank)) &&
  word.right.all (fun s => decide (s=.blank))
def advanceBlank (word : Tape Bool) : Bool :=
  word.left.all (fun s => decide (s=.blank)) && word.right.all (fun s => decide (s=.blank))

def rawSnapshot {L : Type} (c : NativeZipper.Config RawDimensionLoader.Port L) : NativeZipper.Config RawDimensionLoader.Port L :=
  let t0 := c.core.tapes (.payload)
  let h0 := c.pos (.payload)
  let t1 := c.core.tapes (.loader (.work .candidate))
  let h1 := c.pos (.loader (.work .candidate))
  let t2 := c.core.tapes (.loader (.work .square))
  let h2 := c.pos (.loader (.work .square))
  let t3 := c.core.tapes (.loader (.work .bits))
  let h3 := c.pos (.loader (.work .bits))
  let t4 := c.core.tapes (.loader (.work .threshold))
  let h4 := c.pos (.loader (.work .threshold))
  let t5 := c.core.tapes (.loader (.work .unit))
  let h5 := c.pos (.loader (.work .unit))
  let t6 := c.core.tapes (.loader (.work .zero))
  let h6 := c.pos (.loader (.work .zero))
  let t7 := c.core.tapes (.loader (.work .fuel))
  let h7 := c.pos (.loader (.work .fuel))
  let t8 := c.core.tapes (.loader (.work .scratch))
  let h8 := c.pos (.loader (.work .scratch))
  let t9 := c.core.tapes (.loader (.work .copyThreshold))
  let h9 := c.pos (.loader (.work .copyThreshold))
  let t10 := c.core.tapes (.loader (.work .product))
  let h10 := c.pos (.loader (.work .product))
  let t11 := c.core.tapes (.loader (.work .repeatFuel))
  let h11 := c.pos (.loader (.work .repeatFuel))
  let t12 := c.core.tapes (.loader (.work .length))
  let h12 := c.pos (.loader (.work .length))
  let t13 := c.core.tapes (.loader .source)
  let h13 := c.pos (.loader .source)
  let t14 := c.core.tapes (.loader .extra)
  let h14 := c.pos (.loader .extra)
  ⟨⟨c.core.pc,fun p => match p with
    | .payload => t0
    | .loader (.work .candidate) => t1
    | .loader (.work .square) => t2
    | .loader (.work .bits) => t3
    | .loader (.work .threshold) => t4
    | .loader (.work .unit) => t5
    | .loader (.work .zero) => t6
    | .loader (.work .fuel) => t7
    | .loader (.work .scratch) => t8
    | .loader (.work .copyThreshold) => t9
    | .loader (.work .product) => t10
    | .loader (.work .repeatFuel) => t11
    | .loader (.work .length) => t12
    | .loader .source => t13
    | _ => t14
  ⟩,fun p => match p with
    | .payload => h0
    | .loader (.work .candidate) => h1
    | .loader (.work .square) => h2
    | .loader (.work .bits) => h3
    | .loader (.work .threshold) => h4
    | .loader (.work .unit) => h5
    | .loader (.work .zero) => h6
    | .loader (.work .fuel) => h7
    | .loader (.work .scratch) => h8
    | .loader (.work .copyThreshold) => h9
    | .loader (.work .product) => h10
    | .loader (.work .repeatFuel) => h11
    | .loader (.work .length) => h12
    | .loader .source => h13
    | _ => h14
  ⟩

theorem rawSnapshot_eq {L : Type} (c : NativeZipper.Config RawDimensionLoader.Port L) : rawSnapshot c=c := by
  cases c with
  | mk core pos =>
    cases core with
    | mk pc tapes =>
      dsimp only [rawSnapshot]
      congr 2 <;> funext p <;> fin_cases p <;> rfl


def rawPorts : List RawDimensionLoader.Port := [.payload,.loader (.work .candidate),.loader (.work .square),.loader (.work .bits),.loader (.work .threshold),.loader (.work .unit),.loader (.work .zero),.loader (.work .fuel),.loader (.work .scratch),.loader (.work .copyThreshold),.loader (.work .product),.loader (.work .repeatFuel),.loader (.work .length),.loader .source,.loader .extra]
def rawHeads (p : RawDimensionLoader.Port) : Int :=
  match rawPorts.idxOf p with | i => 31*(i:Int)-317

def rawRun (input : List Bool) : Nat → Nat → NativeIOZipper.Config RawDimensionLoader.Port RawDimensionLoader.Label →
    Nat × NativeIOZipper.Config RawDimensionLoader.Port RawDimensionLoader.Label
  | 0,t,c => (t,c)
  | fuel+1,t,c => match RawDimensionLoader.program c.work.core.pc with
    | .work .halt | .work .reject => (t,c)
    | _ => let next:=NativeIOZipper.step RawDimensionLoader.program input c
           rawRun input fuel (t+1) {next with work:=rawSnapshot next.work}

def rawCheck (n flavor : Nat) : Nat × Bool :=
  let len:=n*n*advanceWidth n
  let input:=(List.range len).map (fun i => if flavor=0 then false else if flavor=1 then true else decide (i%3=0))
  let c : NativeIOZipper.Config RawDimensionLoader.Port RawDimensionLoader.Label :=
    ⟨⟨⟨RawDimensionLoader.start,RawDimensionLoader.initial⟩,rawHeads⟩,0,[true,false]⟩
  let (t,r):=rawRun input (8300*len) 0 c
  (t,decide (r.work.core.pc=.load .done) &&
    rawPorts.all (fun p => decide (r.work.pos p=rawHeads p)) &&
    advanceMarkedExact (r.work.core.tapes .payload) input &&
    advanceMarkedExact (r.work.core.tapes (.loader (.work .candidate))) (advanceBits n.size n) &&
    rawPorts.all (fun p => if p=.payload ∨ p=.loader (.work .candidate) then true else advanceBlank (r.work.core.tapes p)) &&
    decide (r.inputPos=len) && decide (r.outRev=[true,false]))

#eval [1,2,3,4,5,8,9].map (fun n => (n,[0,1,2].map (rawCheck n)))
